from fastapi import APIRouter, HTTPException, status, Response
from typing import Dict, List

from ..models import NoteCreate, Note

router = APIRouter()

# In‑memory storage
_notes: Dict[int, str] = {}
_next_id: int = 1


@router.post("/", response_model=Note, status_code=status.HTTP_201_CREATED)
def create_note(note: NoteCreate) -> Note:
    global _next_id
    note_id = _next_id
    _notes[note_id] = note.content
    _next_id += 1
    return Note(id=note_id, content=note.content)


@router.get("/", response_model=List[Note])
def list_notes() -> List[Note]:
    return [Note(id=nid, content=content) for nid, content in _notes.items()]


@router.get("/{note_id}", response_model=Note)
def get_note(note_id: int) -> Note:
    if note_id not in _notes:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Note not found")
    return Note(id=note_id, content=_notes[note_id])


@router.delete("/{note_id}", status_code=status.HTTP_204_NO_CONTENT)
def delete_note(note_id: int) -> Response:
    if note_id not in _notes:
        raise HTTPException(status_code=status.HTTP_404_NOT_FOUND, detail="Note not found")
    del _notes[note_id]
    return Response(status_code=status.HTTP_204_NO_CONTENT)
